    # 投稿文字数上限の計算
    def calculate_max_sentence_length
      base_length = 100
      additional_length = 0

      # TODO：基本増加；自分の投稿数に応じた増加（毒）
      # TODO：寸志: 自分の投稿の後続に自分以外の2名以上が投稿した数（毒）
      # TODO：ボーナス: 評価に応じた増加（毒）

      base_length + additional_length
